def write_lf(relative: str, content: str) -> None:
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(content.rstrip() + "\n")


def replace_once(relative: str, old: str, new: str) -> None:
    path = ROOT / relative
    content = path.read_text(encoding="utf-8")
    if new in content:
        return
    if old not in content:
        raise RuntimeError(f"Missing patch marker in {relative}: {old[:100]!r}")
    write_lf(relative, content.replace(old, new, 1))


def png_chunk(kind: bytes, payload: bytes) -> bytes:
    return struct.pack(">I", len(payload)) + kind + payload + struct.pack(">I", zlib.crc32(kind + payload) & 0xFFFFFFFF)


def create_icon(size: int, maskable: bool) -> bytes:
    margin = int(size * (0.18 if maskable else 0.08))
    center = (size - 1) / 2
    radius = size * (0.33 if maskable else 0.4)
    rows = []
    for y in range(size):
        row = bytearray([0])
        for x in range(size):
            distance = math.hypot(x - center, y - center)
            background = (10, 7, 25, 255)
            if margin <= x < size - margin and margin <= y < size - margin:
                background = (25, 15, 48, 255)
            if distance < radius:
                glow = max(0.0, 1.0 - distance / radius)
                background = (
                    int(90 + 110 * glow),
                    int(50 + 80 * glow),
                    int(130 + 100 * glow),
                    255,
                )
            if abs(x - center) < max(2, size // 42) or abs(y - center) < max(2, size // 42):
                if distance < radius * 0.75:
                    background = (244, 222, 160, 255)
            row.extend(background)
        rows.append(bytes(row))
    raw = b"".join(rows)
    ihdr = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + png_chunk(b"IHDR", ihdr) + png_chunk(b"IDAT", zlib.compress(raw, 9)) + png_chunk(b"IEND", b"")


for relative, content in FILES.items():
    write_lf(relative, content)

for size in (192, 512):
    (ROOT / f"icon-{size}.png").write_bytes(create_icon(size, False))
    (ROOT / f"icon-maskable-{size}.png").write_bytes(create_icon(size, True))

for patch in PATCHES:
    replace_once(patch["relative"], patch["old"], patch["new"])

